<# .SYNOPSIS Reports ADR-016 local database/role state without secret output. #>
[CmdletBinding()]
param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$envPath=Join-Path $root '.env.local'
if(!(Test-Path $envPath)){throw "Missing $envPath"};$h=@{};Get-Content $envPath|ForEach-Object{$x=$_.Trim();if($x -and !$x.StartsWith('#')){$i=$x.IndexOf('=');if($i-gt 0){$h[$x.Substring(0,$i)]=$x.Substring($i+1)}}}
foreach($k in @('POSTGRES_HOST','POSTGRES_PORT','POSTGRES_ADMIN_USER','POSTGRES_ADMIN_PASSWORD')){if(!$h[$k]){throw "Missing $k"}}
$psql=(Get-Command psql -CommandType Application -ErrorAction Stop).Source;$old=$env:PGPASSWORD;try{$env:PGPASSWORD=$h.POSTGRES_ADMIN_PASSWORD;& $psql -X -v ON_ERROR_STOP=1 -h $h.POSTGRES_HOST -p $h.POSTGRES_PORT -U $h.POSTGRES_ADMIN_USER -d postgres -P pager=off -c "SELECT datname AS database, pg_get_userbyid(datdba) AS owner FROM pg_database WHERE datname IN ('identity_db','identity_test_db','auction_db','auction_test_db','bidding_db','bidding_test_db','billing_db','billing_test_db') ORDER BY datname";if($LASTEXITCODE-ne 0){exit $LASTEXITCODE};& $psql -X -v ON_ERROR_STOP=1 -h $h.POSTGRES_HOST -p $h.POSTGRES_PORT -U $h.POSTGRES_ADMIN_USER -d postgres -P pager=off -c "SELECT rolname, rolcanlogin, rolsuper, rolcreatedb, rolcreaterole, rolreplication, rolbypassrls, rolinherit, rolconnlimit FROM pg_roles WHERE rolname ~ '^(identity|auction|bidding|billing)_(test_)?(owner|migrator|app)$' ORDER BY rolname"}finally{if($null-eq$old){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$old}}
